  read:function(){ var p=this.p, c=calc(p), cc=p.kind==='acid'?'[H⁺]':'[OH⁻]'; return [RD('정확한 pH',num(c.exact,2),'','hl'),RD('단순 계산 pH',num(c.naive,2),'','th'),RD('차이',num(c.exact-c.naive,2),''),RD('액성',c.exact<6.95?'산성':c.exact>7.05?'염기성':'중성',''),RD('용질의 농도',sci(c.c,1),'M'),RD('물이 내놓는 이온',sci(Math.min(1e-7,Math.sqrt(KW)),1),'M')]; },
