    var fs=26/Math.max(p.m1,p.m2)/G; [[cx-dx,by1,p.m1],[cx+dx,by2,p.m2]].forEach(function(b){ H.arrow(g,b[0],b[1]+sz(b[2])*0.5,b[0],b[1]+sz(b[2])*0.5+b[2]*G*fs*1.6+4,C.red,2,6); H.arrow(g,b[0],b[1]-2,b[0],b[1]-2-Tn*fs*1.6-4,C.fry,2,6); });
    lab(g,'장력 T',cx+dx+s2/2+8,by2-6,C.fry,'left',11.5); lab(g,'중력 mg',cx+dx+s2/2+8,by2+s2+4,C.red,'left',11.5);
    var v=pane(g,gr,0,Math.max(1,Math.max(2,Math.abs(a)>0.01?Math.sqrt(2*LEN/Math.abs(a))*1.15:3)),0,Math.max(1,Math.abs(a)>0.01?Math.sqrt(2*LEN*Math.abs(a))*1.2:1),{xl:'t (s)',yl:'v (m/s)',xs:0.5,ys:0.5});
