      var w=pane(g,B,0,22,-6,8,{xl:'진동수 f (×10¹⁴ Hz)',yl:'정지 전압 V₀ (V)',xs:5,ys:2}); curve(g,w,function(f){ return HC/(299792458/(f*1e14)*1e9)-phi(p); },C.cyan,2.5,null,phi(p)/0.41357,22);
