    var ly=by+bh+16; H.dot(g,bx+6,ly,4,TH.dim); lab(g,'HA',bx+14,ly,TH.dim,'left',11.5); H.dot(g,bx+60,ly,4,C.blu); lab(g,'A⁻',bx+68,ly,C.blu,'left',11.5); H.dot(g,bx+110,ly,3,C.red); lab(g,'H⁺',bx+118,ly,C.red,'left',11.5); lab(g,F('분자 {0}개 중 이온화한 것 {1}개',n,ion),bx+bw,ly,TH.text,'right',11.5);
