  noPlay:true,
  params:[P('pKa','약산의 pKa',2,10,0.01,4.76,'',[[4.76,'아세트산 4.76'],[3.75,'폼산 3.75']],{d:2}),P('Ca','약산의 농도',0.05,0.5,0.01,0.1,'M'),P('Va','약산의 부피',10,50,1,25,'mL'),P('Cb','염기(NaOH)의 농도',0.05,0.5,0.01,0.1,'M'),P('pct','넣은 염기의 양 (당량점 = 100%)',0,200,0.5,50,'%',[[50,'50 (반당량점)'],[100,'100 (당량점)']],{d:1})],
  cols:[{k:'pKa',l:'약산의 pKa',d:2},{k:'pct',l:'넣은 염기의 양',u:'%',d:1},{k:'pH',l:'pH',d:3},{k:'pHhalf',l:'반당량점의 pH',d:3}], gx:'pKa', gy:'pHhalf', fit:true,
  fitHint:function(m,b,x,y){ if(x==='pKa'&&y==='pHhalf') return F('기울기 {0} ≈ 1, y절편 {1} ≈ 0: 반당량점의 pH = pKa',fmt(m,3),fmt(b,3)); },
