function wat(x){ var c=Math.abs(x)/VOL, h=x>=0?(-c+Math.sqrt(c*c+4*KW))/2:(c+Math.sqrt(c*c+4*KW))/2; return -Math.log10(h); }
function cap(p){ var pH=buf(p,0), h=Math.pow(10,-pH); return 2.303*p.C*KA*h/Math.pow(KA+h,2)*VOL; }
